"""Generated BYTES launch declarations and exact identity inventories."""
from copy import deepcopy
from fractions import Fraction
import hashlib
import json
from pathlib import Path
import unittest

from joulewise.b5 import plan
from joulewise.b6 import registration, session_paths, model_files
from joulewise.flags.collect import read_identity_pins, runtime_versions_sha256
from joulewise.identity_pins import (validate_identity_pin_projection, _read_unit_configs,
                                    STACK_IDENTITY_FIELDS, stack_identity_sha256)
from scripts import bytes_plan_trees as generator

ROOT = Path(__file__).resolve().parents[1]


def read(path):
    return json.loads(path.read_bytes())


class BytesPlanTreesTests(unittest.TestCase):
    def test_every_loop_pack_tree_authenticates_through_its_sidecar(self):
        # Members read the committed pack, not the smoke's staged copy, and
        # refuse when plan_tree.sha256 is absent (r1-bytes-s1-p1: 143 of 143).
        from joulewise.arm_readiness import _plan_tree
        refs = sorted({read(path)["plan_tree_ref"] for path in (ROOT / "configs/b6/packs").glob("*/registration.json")})
        self.assertEqual(len([ref for ref in refs if "/bytes-s" in ref]), 12)
        for ref in refs:
            with self.subTest(ref=ref):
                _plan_tree((ROOT / ref).parent)

    def test_production_launch_declaration_and_runtime_roots(self):
        template = read(ROOT / "configs/campaigns/d117_floor_qwen3-1p7b_v5/plan_tree.json")["arm_attachments"]["launch"]
        runtime = read(ROOT / "configs/b6/loop_bytes.json")
        self.assertEqual(runtime["loop_root"], "/Users/edr/night-b6/loop-bytes")
        for number in range(1, 7):
            for pass_number in (1, 2):
                pack = f"bytes-s{number}-p{pass_number}"
                tree = read(ROOT / f"configs/campaigns/{pack}/plan_tree.json")
                expected = deepcopy(template)
                for row in expected["bindings"]:
                    if row["name"] in ("claim_runs_root", "bound_runs_root"):
                        row["leaf"] = tree["roots"]["claim_root_leaf" if row["name"] == "claim_runs_root" else "bound_root_leaf"]
                self.assertEqual(tree["arm_attachments"]["launch"], expected)
                self.assertEqual(len(plan.declared_bindings(tree)), 14)
                paths = session_paths.for_session(ROOT, runtime["loop_root"], "r1-" + pack)
                self.assertEqual(paths.runs_parent, Path("/Users/edr/night-b6/sessions") / ("r1-" + pack) / "runs-parent")
                for missing in range(14):
                    broken = deepcopy(tree)
                    del broken["arm_attachments"]["launch"]["bindings"][missing]
                    with self.assertRaisesRegex(plan.WindowPlanError, "exactly the fourteen"):
                        plan.declared_bindings(broken)

    def test_identity_projection_covers_real_dispatch_and_preserves_source_bytes(self):
        sources = read(ROOT / "configs/bytes/identity_pins.json")["units"]
        originals = {}
        for unit in sources.values():
            for path in unit["config_paths"]:
                originals[Path(path).name] = (ROOT / path).read_bytes()
        for path in sorted((ROOT / "configs/campaigns").glob("bytes-s*-p*/plan_tree.json")):
            tree = read(path)
            projection = validate_identity_pin_projection(tree["arm_attachments"]["identity_pin_projection"])
            self.assertEqual(projection["state"], "unprojected")
            self.assertIsNone(projection["projection_receipt"])
            dispatched = {}
            for dispatch in plan.resolve_stage_dispatches(tree, ROOT):
                self.assertIsNone(dispatch.error)
                manifest_path = ROOT / dispatch.config_dir / "order_manifest.json"
                for row in read(manifest_path)["executed_order"]:
                    config = manifest_path.parent / row["config"]
                    self.assertEqual(config.read_bytes(), originals[config.name])
                    dispatched[config.relative_to(path.parent).as_posix()] = hashlib.sha256(config.read_bytes()).hexdigest()
            inventory = {}
            for unit in projection["identity_units"]:
                _read_unit_configs(path.parent, unit)  # actual path/hash/schema reader
                self.assertEqual(set(unit["model_runtime_config"].values()), {None})
                inventory.update({row["path"]: row["sha256"] for row in unit["config_inventory"]})
            self.assertEqual(inventory, dispatched)
            self.assertEqual(len(inventory), len(tree["science"]) + 25)

    def test_consumed_identity_pins_separate_file_and_runtime_evidence(self):
        path = ROOT / "configs/b6/registration/identity_pins.json"
        pins = registration.load_identity_pins(path)
        consumed = read_identity_pins(path)
        self.assertEqual(consumed["runtime_versions_sha256"], runtime_versions_sha256(pins["runtime_versions"]))
        evidence = pins["bytes_c4"]
        self.assertTrue(evidence["runtime_stack_observed"])
        self.assertFalse(evidence["runtime_observation"]["model_loaded"])
        self.assertEqual(evidence["runtime_observation"]["executed_interpreter"]["executable"],
                         "/Users/edr/code/JouleWise/.venv/bin/python")
        self.assertEqual(evidence["file_source"]["sha256"], hashlib.sha256((ROOT / evidence["file_source"]["path"]).read_bytes()).hexdigest())
        for row in evidence["packs"]:
            self.assertEqual(row["plan_tree"]["sha256"], hashlib.sha256((ROOT / row["plan_tree"]["path"]).read_bytes()).hexdigest())
        source = read(ROOT / evidence["file_source"]["path"])
        for name, original in source["units"].items():
            entry = pins["units"][name]
            self.assertEqual(consumed["model_artifact_sha256"][name], original["model_artifact_sha256"])
            files = entry["bytes_file_evidence"]
            self.assertTrue(files["runtime_stack_observed"])
            self.assertEqual(files["config_count"], len(files["config_inventory"]))
            self.assertIn("tokenizer.json", files["tokenizer_and_config_files"])
            self.assertIn("config.json", files["tokenizer_and_config_files"])

    def test_generator_check(self):
        generator.generate(check=True)

    def test_c4_stacks_bind_tokenizer_quantization_and_runtime(self):
        pins = read(ROOT / 'configs/b6/registration/identity_pins.json')
        expected = model_files.expected(pins)
        for name in [name for group in generator.GROUPS for name in group]:
            pin = pins['units'][name]
            stack = pin['stack_identity']
            self.assertEqual(set(stack), set(STACK_IDENTITY_FIELDS), name)
            self.assertEqual(pin['runtime_identity_sha256'], stack_identity_sha256(stack), name)
            observed = {'status': 'ok', 'model_source': pin['model_source'],
                        'model_artifact_sha256': pin['model_artifact_sha256'],
                        'runtime': stack['runtime_version']['name'],
                        'runtime_version': stack['runtime_version']['version'],
                        'quantization': deepcopy(stack['quantization']),
                        **{key: deepcopy(stack[key]) for key in ('os_version', 'hardware_unit', 'sampler_output_policy', 'telemetry_backend')},
                        'tokenizer': deepcopy(stack['tokenizer_identity'])}
            self.assertEqual(model_files.compare(expected, observed), [], name)
            for field, value in (('runtime_version', 'different'),
                                 ('os_version', 'different'), ('hardware_unit', {'device': 'different'}),
                                 ('sampler_output_policy', {'sampler': {'temperature': 0.7}}),
                                 ('telemetry_backend', 'different'),
                                 ('quantization', {'bits': 3, 'group_size': 32, 'name': 'different'}),
                                 ('tokenizer', {'identifier': 'different', 'vocab_size': 1})):
                changed = {**observed, field: value}
                self.assertIn('model.stack_differs_from_registered',
                              [row['code'] for row in model_files.compare(expected, changed)], (name, field))

    def test_module_minutes_use_c5_operands_and_keep_registration_gate_open(self):
        sizing_path = ROOT / generator.SIZING_PATH
        sized = read(sizing_path)
        # The executable binding must match the actual agreeing source bytes.
        agreed_version = hashlib.sha256((ROOT / "joulewise/bytes_analysis.py").read_bytes()).hexdigest()
        self.assertEqual(generator.AGREED_ESTIMATOR_VERSION, agreed_version)
        estimator_section = (ROOT / "docs/registrations/bytes_pack_v1.md").read_text().split(
            "## 13. Estimators\n", 1)[1].split("\n## 14.", 1)[0]
        self.assertIn("bound to the agreeing SHA-256 recorded in each pass-1 pack registration", estimator_section)
        for number in range(1, 7):
            allowances = sized["packs"][f"bytes-s{number}-p1"]["disk_derivation"]["allowances_by_model"]
            for pass_number in (1, 2):
                pack = f"bytes-s{number}-p{pass_number}"
                reg = read(ROOT / f"configs/b6/packs/{pack}/registration.json")
                collection = read(ROOT / f"configs/campaigns/{pack}/collection_plan.json")
                expected_status = "registered" if pass_number == 1 else "draft"  # pass 1 gate 2026-10-25
                self.assertEqual(reg["status"], expected_status)
                self.assertEqual(collection["status"], expected_status)
                self.assertEqual(collection["modules"], reg["modules"])
                expected_version = agreed_version if pass_number == 1 else None
                self.assertEqual({entry["version"] for entry in reg["estimators"]}, {expected_version})
                for module in reg["modules"]:
                    terms = allowances[module["module_id"].removeprefix("bytes-")]
                    seconds = terms["member_allowance_s"]
                    exact = Fraction(seconds["numerator"], seconds["denominator"]) * terms["count"] / 60
                    self.assertEqual(module["est_minutes"], float(exact))
                    self.assertEqual(module["est_minutes_source"]["sha256"], hashlib.sha256(sizing_path.read_bytes()).hexdigest())
                # A registered pass carries no draft notes (pack_registration refuses them).
                self.assertEqual("draft_notes" in reg, pass_number == 2)
                notes = "\n".join(reg.get("draft_notes", []))
                for stale in ("current blinding code does not consume", "group_size=64 is assumed",
                              "Sub-pack s4 is planned at 254", "Planning minutes use pilot"):
                    self.assertNotIn(stale, notes)


if __name__ == "__main__":
    unittest.main()
